// ==============================================================================
// File: lib/store/songs.dart
// ------------------------------------------------------------------------------
// PURPOSE:
//   Defines the core data model `Song` for the music application. Represents a
//   single audio track with its metadata (ID3 tags) and local file storage path.
//
// FLOW & ARCHITECTURE:
//   1. Data Persistence:
//      - Inherits from HiveObject and uses @HiveType(typeId: 0) to allow Hive NoSQL
//        database serialization.
//      - Connects with `songs.g.dart` (generated by hive_generator / build_runner)
//        which contains the `SongAdapter`.
//   2. Lifecycle & Data Flow:
//      - During app startup (`main.dart`), MP3 files on the device are scanned and
//        their metadata is extracted via `id3` into `Song` objects.
//      - `Song` instances are saved into Hive boxes:
//          * 'songs'       : Master library of all scanned songs.
//          * 'likedsongs'  : User's favorited songs.
//          * Custom boxes  : User playlists, albums, and artist groups.
//      - These objects are consumed throughout the UI (`SongScreen`, `MiniPlayer`,
//        `PlayerScreen`, `searchScreen`, etc.) and used by `currentplay` in
//        `provider_classes.dart` to control audio playback.
// ==============================================================================

import 'package:hive_flutter/hive_flutter.dart';
part 'songs.g.dart';

@HiveType(typeId:0)
class Song extends HiveObject
{
  @HiveField(0)
  String? title;
  @HiveField(1)
  String? artist;
  @HiveField(2)
  String path;
  @HiveField(3)
  String? album;
  @HiveField(4)
  String? Image;
  @HiveField(5)
  String? publisher;
  @HiveField(6)
  String? genre;
  Song({
    this.album,
    this.artist,
    this.title,
    this.Image,
    this.publisher,
    this.genre,
    required this.path
  });
}